pub(super) async fn authority_with_locks_on(
    db: &mut PgConnection,
    request: &ActionRequest,
    actor: WorkflowActor,
    bundle: &PublishedBundle,
    locks: super::row_locks::RowLocks,
) -> AppResult<ActionOriginAuthority> {
    super::native_mcp::structural_on(db, request, actor, bundle).await?;
    match request.context.origin {
        ToolCallOrigin::Workflow => {
            require_workflow_origin(db, request.scope, bundle).await?;
            Ok(ActionOriginAuthority::Workflow)
        }
        ToolCallOrigin::Agent(origin) => {
            let selection =
                selected_with_locks_on(db, request.scope, actor, bundle, origin, locks).await?;
            validate_agent_action(request, &selection)?;
            Ok(ActionOriginAuthority::Agent(Box::new(selection)))
        }
        ToolCallOrigin::ChannelFinal(_) => Err(missing()),
    }
}

/// Prevent a missing agent origin from silently falling through to STEP/global authority.
pub(super) async fn require_workflow_origin(
    db: &mut PgConnection,
    scope: ActionScope,
    bundle: &PublishedBundle,
) -> AppResult<()> {
    let step: String = sqlx::query_scalar(
        "SELECT step_id FROM workflow_executions WHERE company_id=$1 AND run_id=$2 AND id=$3",
    )
    .bind(scope.company.as_uuid())
    .bind(scope.run.as_uuid())
    .bind(scope.execution.as_uuid())
    .fetch_optional(db)
    .await?
    .ok_or_else(missing)?;
    let step = StepId::parse(step).map_err(|_| invalid())?;
    let definition = bundle
        .compiled()
        .graph()
        .definition()
        .steps
        .get(&step)
        .ok_or_else(missing)?;
    if crate::application::workflow::registry::ModelStep::of(definition.step_type.as_str())
        .is_some()
    {
        return Err(missing());
    }
    Ok(())
}

enum ToolInvocation {
    Http(Box<HttpToolCall>),
    Mcp(Box<McpToolCall>),
    Workflow(Box<WorkflowToolCall>),
    Provisioning(Box<ProvisioningToolCall>),
    Escalation(Box<EscalationToolCall>),
    Message(Box<MessageToolCall>),
    Knowledge(Box<KnowledgeToolCall>),
    Memory(Box<MemoryToolCall>),
}
fn invocation(
    tool: &PreparedTool,
    call: ModelToolCallId,
    arguments: Value,
) -> AppResult<ToolInvocation> {
    Ok(match &tool.target {
        AgentToolTarget::Http { connection } => ToolInvocation::Http(Box::new(HttpToolCall {
            origin: crate::application::agent::ToolCallOrigin::Agent(tool.origin),
            connection: *connection,
            operation: tool.name.clone(),
            arguments,
            call,
        })),
        AgentToolTarget::Mcp { connection } => ToolInvocation::Mcp(Box::new(McpToolCall {
            target: McpToolTarget::Agent {
                connection: *connection,
                origin: tool.origin,
            },
            tool: tool.name.clone(),
            arguments,
            call,
        })),
        AgentToolTarget::Workflow { pin } => ToolInvocation::Workflow(Box::new(WorkflowToolCall {
            origin: crate::application::agent::ToolCallOrigin::Agent(tool.origin),
            name: tool.name.clone(),
            pin: pin.clone(),
            call: ToolCallId::new(
                uuid::Uuid::parse_str(call.as_str())
                    .map_err(|_| AppError::BadRequest("Invalid tool call".into()))?,
            ),
            arguments,
        })),
        AgentToolTarget::Provisioning { .. } => {
            ToolInvocation::Provisioning(Box::new(ProvisioningToolCall {
                origin: crate::application::agent::ToolCallOrigin::Agent(tool.origin),
                kind: tool
                    .provisioning_kind()
                    .ok_or_else(|| AppError::BadRequest("Unknown provisioning tool".into()))?,
                arguments,
                call,
            }))
        }
        AgentToolTarget::Escalation { tool: kind } => {
            ToolInvocation::Escalation(Box::new(EscalationToolCall {
                origin: crate::application::agent::ToolCallOrigin::Agent(tool.origin),
                kind: *kind,
                arguments,
                call,
            }))
        }
        AgentToolTarget::Message { .. } => ToolInvocation::Message(Box::new(MessageToolCall {
            origin: crate::application::agent::ToolCallOrigin::Agent(tool.origin),
            kind: tool
                .message_kind()
                .ok_or_else(|| AppError::BadRequest("Unknown message tool".into()))?,
            arguments,
            call,
        })),
        AgentToolTarget::Knowledge => ToolInvocation::Knowledge(Box::new(KnowledgeToolCall {
            origin: crate::application::agent::ToolCallOrigin::Agent(tool.origin),
            call,
            arguments,
        })),
        AgentToolTarget::Memory { tool: memory } => {
            ToolInvocation::Memory(Box::new(MemoryToolCall {
                origin: crate::application::agent::ToolCallOrigin::Agent(tool.origin),
                tool: *memory,
                call,
                arguments,
            }))
        }
    })
}

async fn dispatch(
    &self,
    fence: WorkflowFence,
    tool: &PreparedTool,
    call: ModelToolCallId,
    arguments: Value,
) -> AppResult<AgentToolObservation> {
    // Dropping the handler future cancels the real work; external seams stay boxed.
    let cancel = CancellationToken::new();
    let outcome = async {
        match invocation(tool, call, arguments)? {
            ToolInvocation::Http(call) => {
                remote(Box::pin(self.http.call_tool(fence, *call, &cancel)).await?)
            }
            ToolInvocation::Mcp(call) => {
                remote(Box::pin(self.mcp.call_tool(fence, *call, &cancel)).await?)
            }
            ToolInvocation::Workflow(call) => {
                let workflow = self.workflow.as_ref().ok_or_else(|| {
                    AppError::BadRequest(
                        "Workflow tools are not available to this worker".into(),
                    )
                })?;
                Box::pin(workflow.call_workflow_tool(fence, *call)).await
            }
            ToolInvocation::Provisioning(call) => {
                let provisioning = self.provisioning.as_ref().ok_or_else(|| {
                    AppError::BadRequest(
                        "Provisioning tools are not available to this worker".into(),
                    )
                })?;
                Box::pin(provisioning.call_tool(fence, *call)).await
            }
            ToolInvocation::Escalation(call) => {
                Box::pin(self.escalation_runtime()?.call_tool(fence, *call)).await
            }
            ToolInvocation::Message(call) => {
                message(Box::pin(self.message.call_tool(fence, *call)).await?)
            }
            ToolInvocation::Knowledge(call) => {
                let knowledge = self.knowledge.as_ref().ok_or_else(|| {
                    AppError::ServiceUnavailable(
                        "Knowledge search is unavailable to this worker".into(),
                    )
                })?;
                Box::pin(knowledge.call_knowledge_tool(fence, *call)).await
            }
            ToolInvocation::Memory(call) => {
                let memory = self.memory.as_ref().ok_or_else(|| {
                    AppError::ServiceUnavailable(
                        "Memory tools are unavailable to this worker".into(),
                    )
                })?;
                Box::pin(memory.call_memory_tool(fence, *call)).await
            }
        }
    }
    .await;
    match outcome {
        Err(AppError::KnowledgeRelease { .. }) => {
            Ok(AgentToolObservation::Completed(tool_error(
                crate::app_error::KNOWLEDGE_AUDIENCE_BELOW_CONTENT,
                "The destination cannot receive this run's content",
            )))
        }
        other => other,
    }
}

pub(in crate::adapters::persistence::workflow) async fn actor_hints_on(
    db: &mut PgConnection,
    scope: ActionScope,
    reviewer: Option<WorkflowActor>,
) -> AppResult<Option<ActorAccountHints>> {
    let actor: Option<Uuid> =
        sqlx::query_scalar("SELECT actor_id FROM workflow_runs WHERE company_id=$1 AND id=$2")
            .bind(scope.company.as_uuid())
            .bind(scope.run.as_uuid())
            .fetch_optional(&mut *db)
            .await?;
    let Some(actor) = actor else { return Ok(None) };
    Ok(Some(ActorAccountHints {
        actor,
        reviewer,
        requester: super::super::provisioning::requester_on(db, scope).await?,
    }))
}

pub(super) async fn requester_on(
    tx: &mut PgConnection,
    scope: ActionScope,
) -> AppResult<Option<WorkflowActor>> {
    #[derive(sqlx::FromRow)]
    struct RootRequester {
        id: Uuid,
        actor: Uuid,
        trigger: Uuid,
    }
    let root: Option<RootRequester> = sqlx::query_as(
        "WITH RECURSIVE chain(id, parent, actor, trigger, depth) AS ( \
           SELECT id, parent_run_id, actor_id, trigger_id, 0 FROM workflow_runs \
           WHERE company_id = $1 AND id = $2 \
           UNION ALL \
           SELECT run.id, run.parent_run_id, run.actor_id, run.trigger_id, chain.depth + 1 \
           FROM workflow_runs AS run JOIN chain ON run.company_id = $1 AND run.id = chain.parent \
           WHERE chain.depth < 64) \
         SELECT id, actor, trigger FROM chain WHERE parent IS NULL",
    )
    .bind(scope.company.as_uuid())
    .bind(scope.run.as_uuid())
    .fetch_optional(&mut *tx)
    .await?;
    let Some(root) = root else {
        return Ok(None);
    };
    let sources: Vec<String> = sqlx::query_scalar(
        "SELECT source_key FROM workflow_admissions WHERE company_id = $1 AND run_id = $2 LIMIT 2",
    )
    .bind(scope.company.as_uuid())
    .bind(root.id)
    .fetch_all(&mut *tx)
    .await?;
    let [source] = sources.as_slice() else {
        return Ok(None);
    };
    match requester_source(source) {
        RequesterSource::RootActor => Ok(Some(WorkflowActor::authenticated(root.actor)?)),
        RequesterSource::None => Ok(None),
        RequesterSource::Message(message) => {
            let author: Option<Uuid> = sqlx::query_scalar(
                "SELECT principal.user_id FROM workflow_message_intents AS intent \
                 JOIN messages AS message ON message.company_id = intent.company_id \
                   AND message.id = intent.message_id \
                 JOIN principals AS principal ON principal.company_id = message.company_id \
                   AND principal.id = message.author_principal_id \
                 WHERE intent.company_id = $1 AND intent.id = $2 AND intent.message_id = $3 \
                   AND intent.origin = 'application' AND principal.kind = 'person'",
            )
            .bind(scope.company.as_uuid())
            .bind(root.trigger)
            .bind(message)
            .fetch_optional(&mut *tx)
            .await?
            .flatten();
            author.map(WorkflowActor::authenticated).transpose()
        }
    }
}
